local config = {
  ui_story_5054_50540101_1_dialog_content = "<color=#a8886f>Los pétalos se quemaron hasta convertirse en cenizas antes de tocar el suelo, un recordatorio de los disturbios por los que acaba de pasar este tranquilo jardín.</color>",
  ui_story_5054_50540101_2_dialog_content = "<color=#a8886f>Los senderos, todavía bordeados de flores florecientes a ambos lados, atraviesan puertas laberínticas y conducen a un salón con una cúpula muy alta.</color>",
  ui_story_5054_50540101_3_dialog_content = "<color=#a8886f>Una criada colocó bocadillos en una habitación, luego se dio la vuelta y se fue. Poco después, se podía escuchar un parloteo fuera de la puerta...</color>",
  ui_story_5054_50540101_4_option_content = "(Escuchar a escondidas)",
  ui_story_5054_50540101_5_dialog_content = "Entonces, ¿es realmente la princesa Verónica la que está ahí?",
  ui_story_5054_50540101_6_dialog_content = "Es cierto, lo vi con mis propios ojos.",
  ui_story_5054_50540101_7_dialog_content = "Esos tipos parecen sospechosos. ¿Por qué Su Alteza estaría con ellos?",
  ui_story_5054_50540101_8_dialog_content = "Relájate, la Sra. Rot está con Lady Joshua. No es nuestra preocupación.",
  ui_story_5054_50540101_9_dialog_content = "Pero es raro, sin embargo. ¿No es la Sra. Rot la favorita del Señor de la Ciudad? ¿Por qué no está en la celebración?",
  ui_story_5054_50540101_10_dialog_content = "¿No sabes? Dama Joshua y la Sra. Rot están muy unidas, y es el Señor de la Ciudad quien le dijo a la Sra. Rot que cuidara de Su Señoría.",
  ui_story_5054_50540101_11_dialog_content = "Pero si están tan apretados, ¿por qué Lady Joshua enviar deliberadamente a la Sra. Rot?",
  ui_story_5054_50540101_12_dialog_content = "¡De ninguna manera! Escuché que la Sra. Rot no solo es una pariente lejana de Lady Joshua, ¡pero el último alumno suyo también!",
  ui_story_5054_50540101_13_option_content = "Pariente lejano...?",
  ui_story_5054_50540101_14_dialog_content = "Sí, pero probablemente ya no haya parientes consanguíneos.",
  ui_story_5054_50540101_15_option_content = "¿Último alumno...?",
  ui_story_5054_50540101_16_dialog_content = "Sí. Se suponía que la Sra. Rot era una niña prodigio, pero no tenía orientación.",
  ui_story_5054_50540101_17_dialog_content = "Sus padres buscaron a Sir Caleb a través de conexiones y por casualidad se encontraron con Lady Joshua.",
  ui_story_5054_50540101_18_dialog_content = "Dama Joshua y la Sra. Rot se cayeron bien de inmediato, por lo que fue su mentora durante años.",
  ui_story_5054_50540101_19_dialog_content = "Oye, ¿quién está haciendo preguntas?",
  ui_story_5054_50540101_20_dialog_content = "¿No fuiste tú?",
  ui_story_5054_50540101_21_dialog_content = "Ejem, shhh—",
  ui_story_5054_50540101_22_dialog_content = "Las paredes tienen oídos... Retomaremos esto más tarde.",
  ui_story_5054_50540102_1_dialog_content = "<color=#a8886f>Las brisas que soplan rápidamente rompen hojas y pétalos frescos y deliciosos.</color>",
  ui_story_5054_50540102_2_dialog_content = "<color=#a8886f>¡Crujido!</color>",
  ui_story_5054_50540102_3_dialog_content = "<color=#a8886f>Una carta con los bordes quemados hace un ruido seco y ensordecedor cuando se pisa.</color>",
  ui_story_5054_50540102_4_dialog_content = "¿Qué es esto?",
  ui_story_5054_50540102_5_dialog_content = "¿Encontraste algo, Caleb?",
  ui_story_5054_50540102_6_dialog_content = "Una pila de cartas quemadas, aparentemente pertenecientes a mi hermana...",
  ui_story_5054_50540102_7_option_content = "(Coge uno)",
  ui_story_5054_50540102_8_dialog_content = "<color=#a8886f>En la hoja chamuscada se distinguen vagamente algunas líneas de escritura elegante.</color>",
  ui_story_5054_50540102_9_dialog_content = "\"Hijo de Montague...\"",
  ui_story_5054_50540102_10_dialog_content = "Conozco la letra y la firma... ¡¿Mi padre escribió esto?!",
  ui_story_5054_50540102_11_dialog_content = "\"Al final, no soy más que un ratón de biblioteca cobarde\".",
  ui_story_5054_50540102_12_dialog_content = "\"Lo único que puedo hacer es irme con...\"",
  ui_story_5054_50540102_13_dialog_content = "\"Espero que tú y el niño vivan felices para siempre\".",
  ui_story_5054_50540102_14_dialog_content = "¿Quién es el hijo de Montague?",
  ui_story_5054_50540102_15_dialog_content = "Ni idea.",
  ui_story_5054_50540102_16_dialog_content = "Mi padre era un erudito compasivo. No me sorprendería si patrocinara a los niños de otras personas.",
  ui_story_5054_50540102_17_dialog_content = "Ejem.",
  ui_story_5054_50540102_18_dialog_content = "<color=#a8886f>Schwartz deja escapar toses débiles, pero la urgencia se manifiesta fuerte y clara.</color>",
  ui_story_5054_50540102_19_dialog_content = "¡No nos preocupemos por eso y vámonos!",
  ui_story_5054_50540103_1_dialog_content = "<color=#a8886f>¡Whoosh!</color>",
  ui_story_5054_50540103_2_dialog_content = "<color=#a8886f>Una joven pelirroja aparece de la nada y detiene a un joven caballero que corre hacia la plaza principal.</color>",
  ui_story_5054_50540103_3_dialog_content = "(Veo dos figuras bloqueando el camino por delante...)",
  ui_story_5054_50540103_4_dialog_content = "Sharona?",
  ui_story_5054_50540103_5_dialog_content = "Lo siento, ¿te conozco?",
  ui_story_5054_50540103_6_dialog_content = "¡Mírate con ese ridículo atuendo de caballero! Desearía no haberte reconocido, pero los cuernos en tu cabeza hacían difícil no hacerlo.",
  ui_story_5054_50540103_7_dialog_content = "¿Quién eres?",
  ui_story_5054_50540103_8_dialog_content = "¿Realmente no puedes decirlo?",
  ui_story_5054_50540103_9_dialog_content = "Todavía no he revisado la última lista de buscados.",
  ui_story_5054_50540103_10_dialog_content = "<color=#a8886f>Las llamas se manifiestan repentinamente detrás de la chica pero luego se dispersan como un aliento exhalado.</color>",
  ui_story_5054_50540103_11_dialog_content = "Está bien, déjame contarte una historia.",
  ui_story_5054_50540103_12_dialog_content = "Una madre con Dragonkin despertó había dado a luz a dos hijas. Su herencia la hizo perder el control y su familia la mató.",
  ui_story_5054_50540103_13_dialog_content = "Para proteger a su dragón a punto de eclosionar, la hija mayor optó por vagar hasta instalarse en Umbraton. La hija menor creció sin saber que su madre había sido asesinada por su tribu.",
  ui_story_5054_50540103_14_dialog_content = "Lo siento, no había escuchado esa historia antes, pero tengo la sensación de que eres esa hija mayor.",
  ui_story_5054_50540103_15_dialog_content = "¿Qué haces en Lumopolis? ¿Eres responsable de lo que pasó en la plaza?",
  ui_story_5054_50540103_16_dialog_content = "Veo que no te dijeron absolutamente nada. Bueno, siéntete libre de seguir sirviendo como el títere de Lumopolis.",
  ui_story_5054_50540103_17_dialog_content = "<color=#a8886f>La chica pelirroja abatida se vuelve, pero Sharona la apunta sin intención de dejarla marchar.</color>",
  ui_story_5054_50540103_18_option_content = "¡Pasando!",
  ui_story_5054_50540103_19_option_content = "¡Los asesinos están aquí ahora!",
  ui_story_5054_50540103_20_dialog_content = "¿Qué?",
  ui_story_5054_50540103_21_dialog_content = "<color=#a8886f>La chica pelirroja desaparece en un abrir y cerrar de ojos, mientras todos ustedes pasan corriendo junto a la confundida Sharona.</color>",
  ui_story_5054_50540201_1_dialog_content = "<color=#a8886f>Cintas de colores, pancartas y decoraciones especiales hacen que la ciudad blanca parezca muy diferente de lo habitual. Te escondes detrás de un gran estandarte y evades a tus perseguidores.</color>",
  ui_story_5054_50540201_2_dialog_content = "<color=#a8886f>Justo cuando estás decidiendo si salir, varias figuras se detienen frente a la pancarta...</color>",
  ui_story_5054_50540201_3_dialog_content = "¿No trajo hoy a la señorita Roshee, duque Troy?",
  ui_story_5054_50540201_4_dialog_content = "(¿Roshee? ¿No es ese el nombre de la infancia de Michael?)",
  ui_story_5054_50540201_5_dialog_content = "Le ordené que se quedara en casa y estudiara. Ella puede participar en tal evento cuando sea mayor.",
  ui_story_5054_50540201_6_dialog_content = "¿Esa sobrina tuya Roshee vagabunda, cazadora de ladrones y anticriminales estaba dispuesta a quedarse en casa y estudiar?",
  ui_story_5054_50540201_7_dialog_content = "Debo aprender técnicas de disciplina infantil de usted algún día, duque Troy.",
  ui_story_5054_50540201_8_dialog_content = "No es nada especial. Aunque Roshee no es mía, es la hija de mi hermana, con la sangre de Troy corriendo por sus venas.",
  ui_story_5054_50540201_9_dialog_content = "Los niños sabrían qué hacer cuando llegue el momento.",
  ui_story_5054_50540201_10_dialog_content = "Señor...",
  ui_story_5054_50540201_11_dialog_content = "¿Por qué te ves tan estresado?",
  ui_story_5054_50540201_12_dialog_content = "¡La señorita Roshee se escapó!",
  ui_story_5054_50540201_13_dialog_content = "Te dejaré ir, duque Troy. Nos vemos en el estrado.",
  ui_story_5054_50540201_14_dialog_content = "Lo haremos, duque Hermes.",
  ui_story_5054_50540201_15_dialog_content = "<color=#a8886f>Después de que Lachon se va, Otto se vuelve sombrío.</color>",
  ui_story_5054_50540201_16_dialog_content = "¡Cómo pudiste mencionar eso frente a otras personas, escoria!",
  ui_story_5054_50540201_17_dialog_content = "Lo siento, señor, tenía mucha prisa... ¡No volverá a suceder!",
  ui_story_5054_50540201_18_dialog_content = "¡No habrá una próxima vez!",
  ui_story_5054_50540201_19_dialog_content = "¿Roshee mencionó adónde va?",
  ui_story_5054_50540201_20_dialog_content = "No... Pero la criada dijo que recibió una nota por la ventana antes de irse.",
  ui_story_5054_50540201_21_dialog_content = "<color=#a8886f>Otto sigue al sirviente a casa, pero la serenidad se ve interrumpida de inmediato por los apresurados soldados y la gente del pueblo.</color>",
  ui_story_5054_50540202_1_dialog_content = "<color=#a8886f>Gritos intermitentes vienen de la plaza. Algunos fugitivos afortunados inician aeronaves en su intento de abandonar la ciudad flotante supuestamente más segura.</color>",
  ui_story_5054_50540202_2_dialog_content = "<color=#a8886f>Mientras tanto, en un rastro apenas perceptible, ves dos figuras familiares.</color>",
  ui_story_5054_50540202_3_dialog_content = "<color=#a8886f>La chica pelirroja, Leona, con una carta en la mano, está conversando con alguien inesperadamente.</color>",
  ui_story_5054_50540202_4_dialog_content = "¡Alto!",
  ui_story_5054_50540202_5_dialog_content = "¿Qué?",
  ui_story_5054_50540202_6_dialog_content = "(¿Se conocen?)",
  ui_story_5054_50540202_7_dialog_content = "¿Incitaste a Roshee a huir de casa?",
  ui_story_5054_50540202_8_dialog_content = "Si te refieres a esa chica que estaba hablando conmigo, entonces te equivocaste de persona.",
  ui_story_5054_50540202_9_dialog_content = "Me confundió con una Kartima y me pidió que le diera esta carta a Sharona Kartima.",
  ui_story_5054_50540202_10_dialog_content = "Pásame la carta.",
  ui_story_5054_50540202_11_dialog_content = "Aunque soy reacio a ayudarla, estoy seguro de que no tengo que responderle a una gente grosera.",
  ui_story_5054_50540202_12_dialog_content = "No puedo creer que haya alguien en Lumopolis que no me reconozca, Otto Troy...",
  ui_story_5054_50540202_13_dialog_content = "<color=#a8886f>¡Whoosh!</color>",
  ui_story_5054_50540202_14_dialog_content = "<color=#a8886f>Antes de que Duke Troy termine, la chica pelirroja prende fuego a una esquina de la carta.</color>",
  ui_story_5054_50540202_15_dialog_content = "¿Qué? ¡Arréstenla!",
  ui_story_5054_50540202_16_dialog_content = "<color=#a8886f>La carta en llamas pasa a la deriva frente a tus ojos y, antes de que se incinere, distingues parte de la escritura...</color>",
  ui_story_5054_50540202_17_dialog_content = "\"El incidente de Eclipsite de hace un año... Detrás de escena... Duke Otto Troy... increíble... no puedo quedarme más...\"",
  ui_story_5054_50540202_18_dialog_content = "<color=#a8886f>Chisporrotear...</color>",
  ui_story_5054_50540202_19_dialog_content = "<color=#a8886f>La carta se convierte en cenizas y desaparece de las calles inmaculadas de Lumopolis, como en el pasado.</color>",
  ui_story_5054_50540203_1_dialog_content = "<color=#a8886f>Chocar...</color>",
  ui_story_5054_50540203_2_dialog_content = "<color=#a8886f>En el patio junto a la carretera, una torre se derrumba de repente. El polvo cubre la vecindad y obstruye la visión.</color>",
  ui_story_5054_50540203_3_dialog_content = "Tose, tose.",
  ui_story_5054_50540203_4_dialog_content = "<color=#a8886f>Desde un hueco entre escombros, las toses de los ancianos rompen el silencio.</color>",
  ui_story_5054_50540203_5_dialog_content = "(¿Quién es ese que está delante de él?)",
  ui_story_5054_50540203_6_dialog_content = "¿Aún me recuerdas?",
  ui_story_5054_50540203_7_dialog_content = "<color=#a8886f>El anciano mira hacia arriba lentamente antes de mirar a otra parte.</color>",
  ui_story_5054_50540203_8_dialog_content = "no te acuerdas Leona? Ustedes querían romper el huevo de dragón en mi mano...",
  ui_story_5054_50540203_9_dialog_content = "No, tú no.",
  ui_story_5054_50540203_10_dialog_content = "<color=#a8886f>La niña se congela como una estatua, sin palabras durante una larga pausa...</color>",
  ui_story_5054_50540203_11_dialog_content = "Je, la última vez que escuché algo tan absurdo, solo tenía cuatro o cinco años. Ahora, no puedo ser influenciado tan fácilmente.",
  ui_story_5054_50540203_12_dialog_content = "Incluso si me sigues balbuceando que \"Tú no eres quien para salvar a los Kartimas\" como mi madre a quien considerabas loca...",
  ui_story_5054_50540203_13_dialog_content = "Tú no eres quien para salvar a los Kartimas... Tampoco Mime...",
  ui_story_5054_50540203_14_dialog_content = "¡Ella se mostrará pronto! ¡Ella está viniendo!",
  ui_story_5054_50540203_15_dialog_content = "<color=#a8886f>La pelirroja vuelve a enmudecer, pero solo por un segundo, hasta que estalla en carcajadas llenas de pena y tristeza que resuenan en el patio vacío.</color>",
  ui_story_5054_50540203_16_dialog_content = "¡Jajaja! Jajaja-!",
  ui_story_5054_50540203_17_dialog_content = "Sabía que no debía volver por la humillación.",
  ui_story_5054_50540203_18_dialog_content = "<color=#a8886f>Abandonas la ruina tan pronto como puedas ver. Entre los escombros, un anciano espera en su mente al salvador.</color>",
  ui_story_5054_50540301_1_dialog_content = "<color=#a8886f>Ruidos de explosiones, gritos, corazones latiendo y armas duras empalando objetos blandos estallan por todas partes...</color>",
  ui_story_5054_50540301_2_dialog_content = "<color=#a8886f>Las alas gigantes levantan un vendaval tras otro, arrojando polvo sobre los rostros de las personas que huyen de la escena.</color>",
  ui_story_5054_50540301_3_dialog_content = "<color=#a8886f>El sudor, las lágrimas y la sangre superan rápidamente el aroma del perfume que lleva una joven noble. Ella y un joven noble observan con miedo cómo se desarrolla todo...</color>",
  ui_story_5054_50540301_4_option_content = "¡Por aquí, rápido!",
  ui_story_5054_50540301_5_dialog_content = "¡Gracias por mostrarnos una salida! P-Pero, ¿qué está pasando aquí?",
  ui_story_5054_50540301_6_dialog_content = "¡Insurrección! ¡Una insurrección premeditada!",
  ui_story_5054_50540301_7_dialog_content = "Mi Dios de la Luz... ¿Por qué alguien haría eso en Lumopolis?",
  ui_story_5054_50540301_8_dialog_content = "¿No recuerda las consecuencias para aquellos que se opusieron al gobierno de Schwartz, señorita?",
  ui_story_5054_50540301_9_dialog_content = "La Casa Pyrrhus recientemente, luego la Casa Gautier, y la Casa Montague antes de eso...",
  ui_story_5054_50540301_10_dialog_content = "¿Te refieres a las casas de los exiliados?",
  ui_story_5054_50540301_11_dialog_content = "Dios mío... Escuché que hay una camarilla secreta de sobrevivientes que planean su venganza...",
  ui_story_5054_50540301_12_dialog_content = "¡Esto es una locura! ¡Todos se han vuelto locos!",
  ui_story_5054_50540301_13_dialog_content = "¡La venganza es solo un pretexto para aquellos que buscaron destronar! ¡Cegado por la venganza solo te hará vulnerable a la manipulación!",
  ui_story_5054_50540301_14_dialog_content = "(¿Cábala secreta? ¿Destronar?)",
  ui_story_5054_50540301_15_dialog_content = "Ahora no es el momento de reflexionar sobre ello. ¡Tenemos que correr!",
  ui_story_5054_50540301_16_dialog_content = "<color=#a8886f>La pareja se va antes de que puedas preguntarles algo. Miras en su dirección solo para verlos rodeados de insurgentes...</color>",
  ui_story_5054_50540302_1_dialog_content = "<color=#a8886f>Estás familiarizado con la ruta desde la plaza hasta el Schwartz Mansión. Tampoco olvidarás que una vez hubo una torre en el camino que ahora está reducida a polvo.</color>",
  ui_story_5054_50540302_2_dialog_content = "<color=#a8886f>Entre las rocas y los escombros llega la voz ronca y excitada de un anciano.</color>",
  ui_story_5054_50540302_3_dialog_content = "¡Tú! ¡Eres tu!",
  ui_story_5054_50540302_4_dialog_content = "(¿Quién es ese que está delante de él?)",
  ui_story_5054_50540302_5_dialog_content = "¡Finalmente estás aquí para verme!",
  ui_story_5054_50540302_6_dialog_content = "Soy Sharona Kartima. ¿Me conoces?",
  ui_story_5054_50540302_7_dialog_content = "Sharona, que lindo nombre... La profecía me dio la habilidad de reconocerte, pero no revelaría que tienes un nombre tan hermoso.",
  ui_story_5054_50540302_8_dialog_content = "¿Profecía?",
  ui_story_5054_50540302_9_dialog_content = "<color=#a8886f>Los ancianos examinan los alrededores con cautela antes de hablar en voz baja.</color>",
  ui_story_5054_50540302_10_dialog_content = "En el sótano de mi antigua casa hay una reliquia de Kartima, una gran katana llamada Azure Fuego.",
  ui_story_5054_50540302_11_dialog_content = "Ahora es tuyo. Llevar Azure ¡Llama y termina lo que se supone que debes terminar!",
  ui_story_5054_50540302_12_dialog_content = "Azure ¿Fuego? Vi una katana en el estudio del tío Mime con el mismo nombre...",
  ui_story_5054_50540302_13_dialog_content = "¡Cómo se atrevía ese impostor a tomar lo que no le pertenecía!",
  ui_story_5054_50540302_14_dialog_content = "Pero no te preocupes, no importa si mantuvo Azure ¡Llama, te pertenece!",
  ui_story_5054_50540302_15_dialog_content = "¡Solo tú puedes desbloquear su poder!",
  ui_story_5054_50540302_16_dialog_content = "¡Ve, hijo mío, date prisa!",
  ui_story_5054_50540302_17_dialog_content = "<color=#a8886f>Sharon todavía está perdida, pero sabe que dentro de doce años, comandante Sharona de Illumina sostendrá en su mano una gran espada llamada Azure Fuego.</color>"
}
return config
